sqlGroup.select:
select a.id as id, a.name as name, a.job_type as jobType, a.job_assign_status as jobAssignStatus, a.completion_status as completionStatus, a.prod_line_or_dept as prodLineOrDept, a.actual_completed_qty as actualCompletedQty, a.assign_type AS assignType, a.work_qty as workQty, a.work_no as workNo, a.work_content as workContent, a.overtime_hours as overtimeHours, date_format( a.task_date, '%Y-%m-%d' ) as taskDate, a.gm_confirm as gmConfirm, date_format( a.created_time, '%Y-%m-%d %H:%i:%s' ) as createdTime, cs.`name` AS createdStaffName, a.expected_qty AS expectedQty, a.expected_work_hours AS expectedWorkHours
from jml_job_assignment a left join jml_staff cs ON a.created_staff_id = cs.id left join jml_job_assignment_staff b on a.id = b.job_assignment_id
and b.assigned_engineer_staff_id = #{staff.staffId}
and a.created_staff_id = #{staff.staffId}
and (a.name like '%${multiFiled}%' or a.work_no like '%${multiFiled}%')
and a.task_date >= str_to_date(#{startDate},'%Y-%m-%d')
and a.task_date <= date_add(str_to_date(#{endDate},'%Y-%m-%d'),interval 1 day)
and a.prodLineOrDept = #{prodLineOrDept}
group by a.id order by a.update_time desc
